import numpy as np

# Define input size, kernel size, stride, and padding
input_size = (3, 3)
kernel_size = (2, 2)
stride = 1
padding = 0

# Validate input size, kernel size, stride, and padding
if len(input_size) != 2 or len(kernel_size) != 2:
    print("Error: Input size and kernel size must be 2D.")
else:
    if input_size[0] < kernel_size[0] or input_size[1] < kernel_size[1]:
        print("Error: Input size is smaller than kernel size.")
    elif stride <= 0 or padding < 0:
        print("Error: Stride must be positive and padding must be non-negative.")
    else:
        print("Input size, kernel size, stride, and padding are valid.")

